BEGIN;
  UPDATE accounts SET balance = balance - 1000 WHERE id = 1;
  UPDATE accounts SET balance = balance + 1000 WHERE id = 2;
COMMIT;   -- 중간에 실패하면 ROLLBACK 되어 아무 일도 없던 상태

-- 위험: 두 트랜잭션이 같은 값을 읽고 각자 계산해 쓴다
SELECT stock FROM items WHERE id = 1;   -- 둘 다 10 을 읽음
UPDATE items SET stock = 9 WHERE id = 1;

-- 안전 1: 원자적 연산
UPDATE items SET stock = stock - 1 WHERE id = 1 AND stock > 0;
-- 안전 2: 잠그고 읽기
SELECT stock FROM items WHERE id = 1 FOR UPDATE;
